; MOLD second lysine-derived marker (LZD), embedded in a peptide chain.
;
; Correspondence to the renamed seven-bead standalone mapping:
;   BB  = B2 (peptide backbone, formerly BBL in the source mapping)
;   SC1 = S2 (LZD aliphatic arm; formerly L1)
;
; LZD:CE+HE1+HE2 belongs chemically to the inter-marker R2/IM2 bead hosted as
; LZS:SC3.  The atoms are kept here with zero coordinate weight so that they
; do not contaminate the L1 coordinate in the residue-local Vermouth mapping.

[ molecule ]
LZD

[from]
amber99

[to]
martini300C

[ martini ]
BB SC1

[ mapping ]
amber27 amber36 amber99

[ atoms ]
    1     N     BB
    2     H     BB
    3    CA     BB
    4    HA    !BB
    5    CB    SC1
    6   HB1    SC1
    7   HB2    SC1
    8    CG    SC1
    9   HG1    SC1
   10   HG2    SC1
   11    CD    SC1
   12   HD1    SC1
   13   HD2    SC1
   14    CE   !SC1
   15   HE1   !SC1
   16   HE2   !SC1
   17     C     BB
   18     O     BB

[ chiral ]
  CB     CA    N    C
  HB1    CA    N    C
  HB2    CA    N    C

[ chiral ]
  HA     CA    N    CB    C
